CREATE TABLE semantic_templates(id uuid PRIMARY KEY,node_id uuid NOT NULL REFERENCES nodes(id),workspace_id uuid REFERENCES workspaces(id),name text NOT NULL,format text NOT NULL CHECK(format IN('markdown','html','docx','pdf','presentation')),definition jsonb NOT NULL,schema_version text NOT NULL DEFAULT '1.0',created_by uuid REFERENCES principals(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE brand_profiles(id uuid PRIMARY KEY,node_id uuid NOT NULL REFERENCES nodes(id),workspace_id uuid REFERENCES workspaces(id),name text NOT NULL,profile jsonb NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid REFERENCES principals(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(node_id,workspace_id,name,version));
CREATE TABLE canonical_content_blocks(id uuid PRIMARY KEY,node_id uuid NOT NULL REFERENCES nodes(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),kind text NOT NULL,title text,content text NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),approval_status text NOT NULL DEFAULT 'draft' CHECK(approval_status IN('draft','in_review','approved','rejected','superseded')),cko_ids uuid[] NOT NULL DEFAULT '{}',claim_ids uuid[] NOT NULL DEFAULT '{}',content_sha256 char(64) NOT NULL,created_by uuid REFERENCES principals(id),created_at timestamptz NOT NULL DEFAULT now(),supersedes_id uuid REFERENCES canonical_content_blocks(id));
CREATE UNIQUE INDEX canonical_blocks_version_uidx ON canonical_content_blocks(node_id,id,version);
CREATE TABLE deliverables(id uuid PRIMARY KEY,node_id uuid NOT NULL REFERENCES nodes(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),title text NOT NULL,format text NOT NULL CHECK(format IN('markdown','html','docx','pdf','presentation')),template_id uuid NOT NULL REFERENCES semantic_templates(id),brand_profile_id uuid REFERENCES brand_profiles(id),version integer NOT NULL DEFAULT 1 CHECK(version>0),approval_status text NOT NULL DEFAULT 'draft' CHECK(approval_status IN('draft','in_review','approved','rejected','superseded')),manifest jsonb NOT NULL,manifest_sha256 char(64) NOT NULL,created_by uuid REFERENCES principals(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),supersedes_id uuid REFERENCES deliverables(id));
CREATE TABLE deliverable_blocks(deliverable_id uuid NOT NULL REFERENCES deliverables(id) ON DELETE CASCADE,block_id uuid NOT NULL REFERENCES canonical_content_blocks(id),ordinal integer NOT NULL,block_version integer NOT NULL,PRIMARY KEY(deliverable_id,block_id),UNIQUE(deliverable_id,ordinal));
CREATE TABLE deliverable_dependencies(deliverable_id uuid NOT NULL REFERENCES deliverables(id) ON DELETE CASCADE,resource_type text NOT NULL CHECK(resource_type IN('cko','claim','artifact','canonical_block','template','brand_profile','deliverable')),resource_id uuid NOT NULL,resource_version integer,propagation_status text NOT NULL DEFAULT 'current' CHECK(propagation_status IN('current','stale','queued','applied','dismissed')),detected_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(deliverable_id,resource_type,resource_id));
CREATE INDEX deliverable_dependencies_resource_idx ON deliverable_dependencies(resource_type,resource_id,propagation_status);
CREATE TABLE deliverable_renders(id uuid PRIMARY KEY,deliverable_id uuid NOT NULL REFERENCES deliverables(id),version integer NOT NULL,format text NOT NULL,artifact_id uuid REFERENCES artifacts(id),mime_type text NOT NULL,content_sha256 char(64) NOT NULL,render_receipt jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(deliverable_id,version,format,content_sha256));
CREATE TABLE deliverable_approvals(id uuid PRIMARY KEY,deliverable_id uuid NOT NULL REFERENCES deliverables(id),version integer NOT NULL,status text NOT NULL CHECK(status IN('in_review','approved','rejected')),principal_id uuid NOT NULL REFERENCES principals(id),comment text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deliverable_recovery_snapshots(id uuid PRIMARY KEY,deliverable_id uuid NOT NULL REFERENCES deliverables(id),version integer NOT NULL,manifest jsonb NOT NULL,renders jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(deliverable_id,version));
